// сумма чисел меньше n, кратных 3 или 5
func sumMultiples(_ n: Int) -> Int {
    var sum = 0
    for i in 1..<n {
        if i % 3 == 0 || i % 5 == 0 {
            sum += i
        }
    }
    return sum
}

print(sumMultiples(10))

