// "Гена Петров" -> "Г. П."
func initials(_ fullName: String) -> String {
    let parts = fullName.split(separator: " ")
    let first = parts[0].prefix(1).uppercased()
    let last = parts[1].prefix(1).uppercased()
    return "\(first). \(last)."
}

