// сумма цифр: 1990 -> 1 + 9 + 9 + 0 = 19
func digitSum(_ n: Int) -> Int {
    let m = abs(n)
    if m < 10 {
        return m
    }
    return m % 10 + digitSum(m / 10)
}

print(digitSum(1990))

