enum BankError: Error {
    case badAmount
    case notEnough
}

// списание со счёта: новый баланс или ошибка
func withdraw(_ balance: Int, _ amount: Int) throws -> Int {
    guard amount > 0 else { throw BankError.badAmount }
    guard amount <= balance else { throw BankError.notEnough }
    return balance - amount
}

do {
    print(try withdraw(1000, 300))
} catch {
    print("ошибка: \(error)")
}

