enum ParseError: Error {
    case notNumber(String)
}

func parsePort(_ s: String) throws -> Int {
    print("разбираю \(s)")
    defer { print("готово") }
    guard let n = Int(s) else { throw ParseError.notNumber(s) }
    return n
}

do {
    print(try parsePort("8080"))
    print(try parsePort("80a"))
    print("сюда не дойдём")
} catch ParseError.notNumber(let s) {
    print("не число: \(s)")
} catch {
    print("другая ошибка")
}
let port = (try? parsePort("x")) ?? 8080
print(port)

enum ConfigError: Error {
    case badPort(String)
}

func port(_ s: String) throws -> Int {
    [[1]] let n = Int(s), (1...65535).contains(n) else {
        [[2]] ConfigError.badPort(s)
    }
    return n
}

print((try? port("8080")) [[3]] 80)

