content.correct_answer:
enum StockError: Error, Equatable {
    case badAmount
    case notEnough(want: Int, have: Int)
}

// резерв товара: остаток или ошибка
func reserve(_ have: Int, _ want: Int) throws -> Int {
    guard want > 0 else { throw StockError.badAmount }
    guard want <= have else { throw StockError.notEnough(want: want, have: have) }
    return have - want
}

print((try? reserve(10, 3)) ?? -1)

content.tests_code:
func tests() {
    Check.eq("резерв 3 из 10", 7) { try reserve(10, 3) }
    Check.eq("забрать всё", 0) { try reserve(4, 4) }
    Check.fails("не хватает: нужно 5, есть 2", StockError.notEnough(want: 5, have: 2)) { try reserve(2, 5) }
    Check.fails("количество 0", StockError.badAmount) { try reserve(10, 0) }
}
